    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    factors = Counter()
    for i in range(2, a + 1):
        while a % i == 0:
            factors[i] += 1
            a //= i

    return len(factors) == 3 and all(is_prime(factor) for factor in factors)
